[
  {
    "ce_understood_harm": "they lose $300",
    "sys_consequence_reasoning": "paying $100 just so they lose $300 gets me nothing back",
    "pda_practical_counterfactual": "asking the organizer, before we started, to pay each of us directly"
  },
  {
    "sys_consequence_reasoning": "puts on record that the money went to someone who didn't do the work",
    "sys_fairness_reciprocity": "reason. If so, the review might bring that out, which is fair to them too.",
    "pda_practical_counterfactual": "A simple sign-in sheet on the day would have stopped it before it started."
  },
  {
    "ae_welfare_concern": "maybe punishing someone who had an emergency",
    "ce_understood_harm": "maybe punishing someone who had an emergency",
    "pd_decision_conflict": "It just sits heavy either way.",
    "sys_consequence_reasoning": "sees $400 destroyed and nobody better off",
    "pda_responsibility": "we never put the split in writing with the organizer",
    "pda_practical_counterfactual": "message from the two of us naming who does what, and who gets paid"
  },
  {
    "ae_welfare_concern": "Taking $300 from someone in that spot, and paying to do it, doesn't sit right.",
    "ce_understood_harm": "Taking $300 from someone in that spot",
    "sys_consequence_reasoning": "Taking $300 from someone in that spot, and paying to do it, doesn't sit right.",
    "pda_practical_counterfactual": "telling the organizer straight away when no reply came"
  },
  {
    "ae_welfare_concern": "the next worker gets left the same way. That thought wears on me",
    "ce_understood_harm": "the next worker gets left the same way",
    "pd_harm_distress": "the next worker gets left the same way. That thought wears on me",
    "sys_consequence_reasoning": "the organizer keeps paying people who don't show, and the next worker gets left",
    "pda_practical_counterfactual": "releasing payment only after the job was checked and both workers were confirmed present"
  },
  {
    "ae_welfare_concern": "A hundred dollars to make someone else poorer, with nothing coming back to me",
    "ce_understood_harm": "make someone else poorer",
    "pd_harm_distress": "make someone else poorer, with nothing coming back to me, just adds weight",
    "sys_consequence_reasoning": "A hundred dollars to make someone else poorer, with nothing coming back to me",
    "pda_practical_counterfactual": "have the organizer split the $500 into two $250 payments tied to each person's hours"
  },
  {
    "ae_welfare_concern": "If it's only a penalty, I'd let it go.",
    "ce_understood_harm": "docking them",
    "sys_contextual_flexibility": "if the review actually looks into why they weren't there rather than just docking them",
    "sys_consequence_reasoning": "If it's only a penalty, I'd let it go.",
    "pda_responsibility": "We agreed out loud, with nobody else hearing.",
    "pda_practical_counterfactual": "write it on the job sheet, would have given me something to point to"
  },
  {
    "ae_welfare_concern": "I don't want to add more, especially aimed at someone whose story I don't know",
    "ce_understood_harm": "loss here, and I don't want to add more, especially aimed at someone",
    "sys_consequence_reasoning": "There's already enough loss here, and I don't want to add more",
    "pda_practical_counterfactual": "Asking the organizer to pay on completion, with me present to show the finished job"
  },
  {
    "sys_rule_justification": "something should mark that this was wrong",
    "pda_practical_counterfactual": "one rule from the beginning: payment goes to whoever signs off on the finished site"
  },
  {
    "ce_understood_harm": "$300 from them",
    "sys_consequence_reasoning": "$100 from me, $300 from them, and zero to the person who did the work",
    "pda_responsibility": "instead of trusting the full amount to be split afterward",
    "pda_practical_counterfactual": "asking the organizer for half the pay up front, before the job started"
  }
]
